  const supabase = await createClient();
  const { data: auth } = await supabase.auth.getUser();
  if (!auth.user) redirect("/auth/signin?next=/listings/mine");
  const { data, error } = await supabase
    .from("public_listings")
    .select("id,listing_type,title,category,city,country_code,lifecycle_state,moderation_note,paid_promotion,promotion_expires_at,published_at,expires_at,created_at")
    .eq("owner_id", auth.user.id)
    .order("created_at", { ascending: false });

